From 074921f45589f37febdf842a5c638830ba631f4e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:42:35 +0100
Subject: [PATCH] applets/clipboard: allow toggling the action popup from the
 context menu

Turning the automatic action popup on or off needed a global shortcut
that is unset by default or a trip to the settings dialog, so add a
checkable entry for it to the applet's menu and keep the dialog in sync.

BUG: 409803
---
 applets/clipboard/qml/main.qml           | 11 ++++++++++-
 doc/klipper/index.docbook                | 13 +++++++------
 klipper/configdialog.cpp                 | 18 ++++++++++++++++++
 klipper/configdialog.h                   |  1 +
 klipper/declarative/klipperinterface.cpp | 18 ++++++++++++++++++
 klipper/declarative/klipperinterface.h   | 12 ++++++++++++
 klipper/klipper.cpp                      |  9 ++++++++-
 klipper/klipper.h                        |  7 +++++++
 klipper/urlgrabber.cpp                   |  7 +++++++
 klipper/urlgrabber.h                     |  3 +++
 10 files changed, 91 insertions(+), 8 deletions(-)

diff --git a/applets/clipboard/qml/main.qml b/applets/clipboard/qml/main.qml
index 101b18486a..4ee1e8a9c9 100644
--- a/applets/clipboard/qml/main.qml
+++ b/applets/clipboard/qml/main.qml
@@ -84,7 +84,7 @@ PlasmoidItem {
             id: clearAction
             text: i18n("Clear History")
             icon.name: "edit-clear-history"
-            priority: copyClipboardAction.visible || main.clipboardMenu?.editing ? PlasmaCore.Action.LowPriority : PlasmaCore.Action.NormalPriority
+            priority: copyClipboardAction.visible || main.clipboardMenu?.editing ? PlasmaCore.Action.LowPriority : PlasmaCore.Action.HighPriority
             visible: !main.isClipboardEmpty
             onTriggered: main.clipboardMenu.clearHistory()
         },
@@ -98,6 +98,15 @@ PlasmoidItem {
             onTriggered: page.copyAction.triggered()
             enabled: page?.copyAction?.enabled ?? ""
             visible: page instanceof Private.BarcodePage && !page.showHeader
+        },
+        PlasmaCore.Action {
+            text: i18n("Show Action Popup Menu When Copying")
+            icon.name: "show-menu"
+            checkable: true
+            alwaysShowAsMenu: true
+            checked: klipper.automaticActionMenu
+            visible: klipper.actionsOffered
+            onTriggered: klipper.toggleAutomaticActionMenu()
         }
     ]

diff --git a/doc/klipper/index.docbook b/doc/klipper/index.docbook
index 7a0ee45608..22b1820435 100644
--- a/doc/klipper/index.docbook
+++ b/doc/klipper/index.docbook
@@ -109,13 +109,14 @@ where you can also disable the built-in action with
 </para>

 <para>You can always access the matching action menu
-with a button next to the item in your history. You can also choose
-to have an action menu pop up any time
-a match is placed on the clipboard by using the
-<guilabel>Automatic Action Popup Menu</guilabel> shortcut that you can set up
