+context menu of the clipboard icon, by checking
 <guilabel>When text or a file is copied</guilabel> under <guilabel>Show action popup
-menu</guilabel> on the <guilabel>Action Menu</guilabel> page. 
+menu</guilabel> on the <guilabel>Action Menu</guilabel> page, or with a keyboard
+shortcut assigned to that entry on the <guilabel>Shortcuts</guilabel> page.
 There, with the option <guilabel>Automatic action menu time</guilabel>, you can also change how long it takes the automatic
 menu to close on its own if you do not act up on it.</para>

diff --git a/klipper/configdialog.cpp b/klipper/configdialog.cpp
index 592dfd8dd8..61b72be66d 100644
--- a/klipper/configdialog.cpp
+++ b/klipper/configdialog.cpp
@@ -247,6 +247,11 @@ void PopupWidget::setActionsOffered(bool offered)
     m_form->setEnabled(offered);
 }

+void PopupWidget::setActionMenuEnabled(bool enabled)
+{
+    m_enablePopupCb->setChecked(enabled);
+}
+
 //////////////////////////
 //  ActionsWidget       //
 //////////////////////////
@@ -537,6 +542,19 @@ ConfigDialog::ConfigDialog(QWidget *parent, KConfigSkeleton *skeleton, Klipper *

     addPage(shortcutsPage, i18nc("Shortcuts Config", "Shortcuts"), QStringLiteral("preferences-desktop-keyboard"), i18n("Shortcuts Configuration"));

+    // Sync settings across config page and context menu
+    if (m_klipper) {
+        connect(m_klipper, &Klipper::urlGrabberEnabledChanged, this, [this] {
+            m_popupPage->setActionMenuEnabled(m_klipper->urlGrabberEnabled());
+        });
+    }
+    // Sync settings with Keyboard Shortcuts KCM
+    connect(KGlobalAccel::self(), &KGlobalAccel::globalShortcutChanged, this, [this, collection] {
+        if (!m_shortcutsWidget->isModified()) {
+            m_shortcutsWidget->clearCollections();
+            m_shortcutsWidget->addCollection(collection);
+        }
+    });
     connect(m_actionsPage, &ActionsWidget::widgetChanged, this, &ConfigDialog::settingsChangedSlot);
     connect(m_actionsPage, &ActionsWidget::widgetChanged, this, &ConfigDialog::updateActionsOffered);
     connect(m_shortcutsWidget, &KShortcutsEditor::keyChange, this, &ConfigDialog::settingsChangedSlot);
diff --git a/klipper/configdialog.h b/klipper/configdialog.h
index d3d44c97fb..e12bb09e45 100644
--- a/klipper/configdialog.h
+++ b/klipper/configdialog.h
@@ -49,6 +49,7 @@ public:
     ~PopupWidget() override = default;

     void setActionsOffered(bool offered);
+    void setActionMenuEnabled(bool enabled);

 private:
     KMessageWidget *m_noActionsMessage;
diff --git a/klipper/declarative/klipperinterface.cpp b/klipper/declarative/klipperinterface.cpp
index 8ccee5c561..15146b8cdf 100644
--- a/klipper/declarative/klipperinterface.cpp
+++ b/klipper/declarative/klipperinterface.cpp
@@ -6,11 +6,14 @@

 #include "klipperinterface.h"
 #include "klipper.h"
+#include "urlgrabber.h"

 KlipperInterface::KlipperInterface(QObject *parent)
     : QObject(parent)
     , m_klipper(Klipper::self())
 {
+    connect(m_klipper.get(), &Klipper::urlGrabberEnabledChanged, this, &KlipperInterface::automaticActionMenuChanged);
+    connect(m_klipper->urlGrabber(), &URLGrabber::actionsChanged, this, &KlipperInterface::actionsOfferedChanged);
 }

 KlipperInterface::~KlipperInterface() = default;
@@ -20,4 +23,19 @@ void KlipperInterface::configure()
     m_klipper->slotConfigure();
 }

+bool KlipperInterface::automaticActionMenu() const
+{
+    return m_klipper->urlGrabberEnabled();
+}
+
+bool KlipperInterface::actionsOffered() const
+{
+    return m_klipper->urlGrabber()->offersActions();
+}
+
+void KlipperInterface::toggleAutomaticActionMenu()
+{
+    m_klipper->toggleURLGrabberEnabled();
+}
+
 #include "moc_klipperinterface.cpp"
diff --git a/klipper/declarative/klipperinterface.h b/klipper/declarative/klipperinterface.h
index 03c69fccfd..faa8e5cab5 100644
--- a/klipper/declarative/klipperinterface.h
+++ b/klipper/declarative/klipperinterface.h
@@ -19,12 +19,24 @@ class KlipperInterface : public QObject
     Q_OBJECT
     QML_ELEMENT

+    /** Whether the action menu is shown automatically for matching content. */
+    Q_PROPERTY(bool automaticActionMenu READ automaticActionMenu NOTIFY automaticActionMenuChanged)
+    Q_PROPERTY(bool actionsOffered READ actionsOffered NOTIFY actionsOfferedChanged)
+
 public:
     explicit KlipperInterface(QObject *parent = nullptr);
     ~KlipperInterface() override;

     Q_INVOKABLE void configure();

+    bool automaticActionMenu() const;
+    bool actionsOffered() const;
+    Q_INVOKABLE void toggleAutomaticActionMenu();
+
+Q_SIGNALS:
+    void automaticActionMenuChanged();
+    void actionsOfferedChanged();
+
 private:
     std::shared_ptr<Klipper> m_klipper;
 };
diff --git a/klipper/klipper.cpp b/klipper/klipper.cpp
index a8cf144f06..5d0afebe06 100644
--- a/klipper/klipper.cpp
+++ b/klipper/klipper.cpp
@@ -70,7 +70,7 @@ Klipper::Klipper(QObject *parent)

     m_toggleURLGrabAction = new KToggleAction(this);
     m_collection->addAction(QStringLiteral("clipboard_action"), m_toggleURLGrabAction);
-    m_toggleURLGrabAction->setText(i18nc("@action:inmenu Toggle automatic action", "Toggle Automatic Popping Up of Action Menu"));
+    m_toggleURLGrabAction->setText(i18nc("@action:inmenu Toggle automatic action", "Show Action Popup Menu When Copying"));
     m_toggleURLGrabAction->setIcon(QIcon::fromTheme(QStringLiteral("show-menu")));
     KGlobalAccel::setGlobalShortcut(m_toggleURLGrabAction, QKeySequence());
     connect(m_toggleURLGrabAction, &QAction::toggled, this, &Klipper::setURLGrabberEnabled);
@@ -332,12 +332,19 @@ void Klipper::slotRepeatAction(bool fromHistory)
     }
 }

+void Klipper::toggleURLGrabberEnabled()
+{
+    m_toggleURLGrabAction->trigger();
+}
+
 void Klipper::setURLGrabberEnabled(bool enable)
 {
     if (enable != m_bURLGrabber) {
         m_bURLGrabber = enable;
         m_lastURLGrabberText.clear();
         KlipperSettings::setURLGrabberEnabled(enable);
+        KlipperSettings::self()->save();
+        Q_EMIT urlGrabberEnabledChanged();
     }

     m_toggleURLGrabAction->setChecked(enable);
