     void editFinished(std::shared_ptr<const HistoryItem> item, int result);
     Q_SCRIPTABLE void clipboardHistoryUpdated();

@@ -84,6 +90,7 @@ public Q_SLOTS:
     void slotPopupMenu();
     void setURLGrabberEnabled(bool);
     void slotRepeatAction(bool fromHistory = false);
+    void toggleURLGrabberEnabled();

 protected Q_SLOTS:
     void showPopupMenu(QMenu *);
diff --git a/klipper/urlgrabber.cpp b/klipper/urlgrabber.cpp
